package com.example.agroconnect.controller;
import com.example.agroconnect.model.*; import com.example.agroconnect.repository.*; import jakarta.servlet.http.HttpSession; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.http.HttpHeaders; import org.springframework.http.MediaType; import org.springframework.core.io.FileSystemResource; import org.springframework.core.io.Resource; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/api/loan-documents") @CrossOrigin(origins="http://localhost:5173",allowCredentials="true") public class LoanDocumentController {private final LoanRepository loans;private final LoanDocumentRepository docs;@Value("${agroconnect.upload-dir:uploads}") private String uploadDir;public LoanDocumentController(LoanRepository l,LoanDocumentRepository d){loans=l;docs=d;} private boolean allowed(Loan l,HttpSession s){Object uid=s.getAttribute("userId");return uid!=null&&("ADMIN".equals(s.getAttribute("role"))||(l.getFarmer()!=null&&l.getFarmer().getUser()!=null&&l.getFarmer().getUser().getId().toString().equals(uid.toString())));}
 @GetMapping("/loan/{loanId}") public ResponseEntity<?> list(@PathVariable Long loanId,HttpSession s){Loan l=loans.findById(loanId).orElse(null);if(l==null)return ResponseEntity.notFound().build();if(!allowed(l,s))return ResponseEntity.status(403).body("Not allowed");return ResponseEntity.ok(docs.findByLoanLoanIdOrderByUploadedAtDesc(loanId));}
 @GetMapping("/{documentId}/download") public ResponseEntity<?> download(@PathVariable Long documentId,HttpSession s){LoanDocument d=docs.findById(documentId).orElse(null);if(d==null)return ResponseEntity.notFound().build();if(!allowed(d.getLoan(),s))return ResponseEntity.status(403).body("Not allowed");try{Path dir=Paths.get(uploadDir).toAbsolutePath().normalize();Path path=dir.resolve(d.getStoredFilename()).normalize();if(!path.startsWith(dir)||!Files.exists(path))return ResponseEntity.notFound().build();Resource resource=new FileSystemResource(path);return ResponseEntity.ok().contentType(MediaType.parseMediaType(Objects.requireNonNullElse(d.getContentType(),"application/octet-stream"))).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+d.getOriginalFilename().replaceAll("[\\\"\\r\\n]","_")+"\"").body(resource);}catch(Exception e){return ResponseEntity.internalServerError().body("Unable to download document");}}
 @PostMapping(value="/loan/{loanId}",consumes="multipart/form-data") public ResponseEntity<?> upload(@PathVariable Long loanId,@RequestParam("file") MultipartFile file,HttpSession s){Loan l=loans.findById(loanId).orElse(null);if(l==null)return ResponseEntity.notFound().build();if(!allowed(l,s))return ResponseEntity.status(403).body("Not allowed");if(file.isEmpty()||file.getSize()>5*1024*1024)return ResponseEntity.badRequest().body("Choose a file up to 5 MB");String name=Objects.requireNonNullElse(file.getOriginalFilename(),"document");String ext=name.contains(".")?name.substring(name.lastIndexOf('.')+1).toLowerCase(Locale.ROOT):"";if(!Set.of("pdf","jpg","jpeg","png").contains(ext))return ResponseEntity.badRequest().body("Only PDF, JPG, JPEG and PNG files are allowed");try{Path dir=Paths.get(uploadDir).toAbsolutePath().normalize();Files.createDirectories(dir);String stored=UUID.randomUUID()+"."+ext;Path target=dir.resolve(stored).normalize();if(!target.startsWith(dir))return ResponseEntity.badRequest().body("Invalid filename");file.transferTo(target);LoanDocument d=new LoanDocument();d.setLoan(l);d.setOriginalFilename(name);d.setStoredFilename(stored);d.setContentType(file.getContentType());d.setFileSize(file.getSize());d.setUploadedBy(String.valueOf(s.getAttribute("userId")));return ResponseEntity.ok(docs.save(d));}catch(Exception e){return ResponseEntity.internalServerError().body("Unable to store document");}}
}
